//! `Quantity<S>` as a typed model column (#69): one `BIGINT` column, exact
//! filters, ordering and `sum`, schema checks.

use renox::db::Migration;
use renox::money::Rounding::HalfEven;
use renox::prelude::*;
use renox::quantity::Quantity;
use renox::testing::TestApp;

type Q3 = Quantity<3>;

const SCHEMA: Migration = Migration::new("20300101000000_quantity_model", "", None)
    .sqlite(
        "CREATE TABLE stocks (id INTEGER PRIMARY KEY AUTOINCREMENT, level BIGINT NOT NULL, reserved BIGINT);",
        None,
    )
    .postgres(
        "CREATE TABLE stocks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, level BIGINT NOT NULL, reserved BIGINT);",
        None,
    );

const MISTYPED: Migration = Migration::new(
    "20300101000000_quantity_mistyped",
    "CREATE TABLE stocks (id INTEGER PRIMARY KEY AUTOINCREMENT, level TEXT NOT NULL, reserved TEXT);",
    None,
);

#[derive(Model, Debug, Clone, PartialEq)]
#[model(table = "stocks")]
struct Stock {
    id: i64,
    level: Q3,
    reserved: Option<Q3>,
}

fn q(text: &str) -> Q3 {
    Q3::parse_exact(text).unwrap()
}

async fn add(db: &Db, level: &str, reserved: Option<&str>) {
    Stock::create(
        db,
        Stock {
            id: 0,
            level: q(level),
            reserved: reserved.map(q),
        },
    )
    .await
    .unwrap();
}

#[test]
fn the_typed_constants_carry_the_quantity_type() {
    use renox::db::Model as _;
    assert_eq!(Stock::COLUMNS, &["id", "level", "reserved"]);
    let _: renox::db::Col<Stock, Q3> = Stock::LEVEL;
    let _: renox::db::Col<Stock, Option<Q3>> = Stock::RESERVED;
}

#[renox::test]
async fn filters_and_ordering_compare_the_scaled_integer() {
    let app = TestApp::new(App::new().migrations(&[SCHEMA])).await;
    let db = app.db();
    add(db, "5.000", Some("0.100")).await;
    add(db, "4.999", None).await;
    add(db, "12.5", Some("0.200")).await;

    let found = Stock::query()
        .where_(Stock::LEVEL.gte(q("5")))
        .order_by(Stock::LEVEL)
        .get(db)
        .await
        .unwrap();
    let levels: Vec<String> = found.iter().map(|s| s.level.to_string()).collect();
    assert_eq!(levels, ["5.000", "12.500"]);

    let below = Stock::query()
        .where_(Stock::LEVEL.lt(q("5")))
        .get(db)
        .await
        .unwrap();
    assert_eq!(below.len(), 1);
    assert_eq!(below[0].reserved, None);

    // A range from two bounds, largest first.
    let range = Stock::query()
        .where_(Stock::LEVEL.gt(q("4.999")))
        .where_(Stock::LEVEL.lte(q("12.5")))
        .order_by_desc(Stock::LEVEL)
        .get(db)
        .await
        .unwrap();
    assert_eq!(range.len(), 2);
    assert_eq!(range[0].level, q("12.5"));

    let with = Stock::query()
        .where_(Stock::RESERVED.gt(q("0.1")))
        .get(db)
        .await
        .unwrap();
    assert_eq!(with.len(), 1);
}

#[renox::test]
async fn sum_is_exact_and_stays_a_quantity() {
    let app = TestApp::new(App::new().migrations(&[SCHEMA])).await;
    let db = app.db();
    add(db, "0.1", Some("0.1")).await;
    add(db, "0.2", Some("0.2")).await;
    let total: Q3 = Stock::query().sum(db, "level").await.unwrap();
    assert_eq!(total, Q3::parse("0.3", HalfEven).unwrap());
    assert_eq!(total.raw(), 300);
    let reserved: Q3 = Stock::query().sum(db, "reserved").await.unwrap();
    assert_eq!(reserved.to_string(), "0.300");
    let none: Q3 = Stock::query()
        .where_(Stock::LEVEL.gt(q("100")))
        .sum(db, "level")
        .await
        .unwrap();
    assert_eq!(none.raw(), 0);
}

#[renox::test]
async fn the_schema_check_accepts_bigint_and_reports_a_mistyped_column() {
    let app = TestApp::new(App::new().migrations(&[SCHEMA]).model::<Stock>()).await;
    app.assert_models_match_schema().await;

    let app = TestApp::new(App::new().migrations(&[MISTYPED]).model::<Stock>()).await;
    let err = tokio::spawn(async move { app.assert_models_match_schema().await })
        .await
        .unwrap_err();
    let payload = err.into_panic();
    let text = payload
        .downcast_ref::<String>()
        .cloned()
        .or_else(|| payload.downcast_ref::<&str>().map(|s| s.to_string()))
        .unwrap();
    assert!(text.contains("level"), "{text}");
    assert!(text.contains("reserved"), "{text}");
}

const MISSING: Migration = Migration::new(
    "20300101000000_quantity_missing",
    "CREATE TABLE stocks (id INTEGER PRIMARY KEY AUTOINCREMENT, level BIGINT NOT NULL);",
    None,
);

/// AC7: a column the model has and the table lacks is reported by name.
#[renox::test]
async fn the_schema_check_reports_a_missing_quantity_column() {
    let app = TestApp::new(App::new().migrations(&[MISSING]).model::<Stock>()).await;
    let err = tokio::spawn(async move { app.assert_models_match_schema().await })
        .await
        .unwrap_err();
    let payload = err.into_panic();
    let text = payload
        .downcast_ref::<String>()
        .cloned()
        .or_else(|| payload.downcast_ref::<&str>().map(|s| s.to_string()))
        .unwrap();
    assert!(text.contains("reserved"), "{text}");
    assert!(!text.contains("`level`"), "{text}");
}
